// ======================
// AdminService Interface
// ======================

// A service for aqueduct introspection and configuration.
type AdminService interface {
	// Query for the number of messages in the state table by state, by queue and by node.
	StateTableCounts(context.Context, *StateTableCountsRequest) (*StateTableCountsResponse, error)

	// Disables scheduling for a queue. Aqueduct will continue to accept scheduled jobs for the queue
	// and will relay scheduled jobs to the state log, but it will drop the jobs in state processor
	// nodes to avoid state table writes. The primary use case for this endpoint is to provide some
	// maneuverability in an incident where a single queue gets a huge number of scheduled jobs and
	// causes evictions, which will affect all queues for an app. To prevent a single queue from
	// affecting scheduling for all queues, disable scheduling for the problem queue.
	DisableScheduling(context.Context, *DisableSchedulingRequest) (*EmptyResponse, error)

	// Resume scheduling for a queue. Requires a state processor rebalance to schedule any jobs that
	// were dropped while scheduling was disabled.
	EnableScheduling(context.Context, *EnableSchedulingRequest) (*EmptyResponse, error)

	// List queues for which scheduling is disabled.
	SchedulingDisabled(context.Context, *SchedulingDisabledRequest) (*SchedulingDisabledResponse, error)

	// Enable auth enforcement for a given app.
	EnforceAuth(context.Context, *EnforceAuthRequest) (*EmptyResponse, error)

	// Disable auth enforcement for a given app.
	DisableAuthEnforcement(context.Context, *DisableAuthEnforcementRequest) (*EmptyResponse, error)

	// List apps that have auth enforcement disabled.
	AuthEnforcementsDisabled(context.Context, *AuthEnforcementsDisabledRequest) (*AuthEnforcementsDisabledResponse, error)

	// Enables the high-throughput pop strategy for an app.
	EnableHighThroughput(context.Context, *EnableHighThroughputRequest) (*EmptyResponse, error)

	// Disables the high-throughput pop strategy for an app.
	DisableHighThroughput(context.Context, *DisableHighThroughputRequest) (*EmptyResponse, error)

	// List apps that use the high-throughput pop strategy.
	HighThroughputEnabled(context.Context, *HighThroughputEnabledRequest) (*HighThroughputEnabledResponse, error)

	// Enables the high-throughput pop strategy for a worker tag.
	EnableHighThroughputTag(context.Context, *EnableHighThroughputTagRequest) (*EmptyResponse, error)

	// Disables the high-throughput pop strategy for a worker tag.
	DisableHighThroughputTag(context.Context, *DisableHighThroughputTagRequest) (*EmptyResponse, error)

	// List worker tags that use the high-throughput pop strategy.
	HighThroughputTagEnabled(context.Context, *HighThroughputTagEnabledRequest) (*HighThroughputTagEnabledResponse, error)

	// Query for queues and associated state.
	DescribeQueues(context.Context, *DescribeQueuesRequest) (*DescribeQueuesResponse, error)

	// Query for runtime configuration.
	DescribeConfig(context.Context, *DescribeConfigRequest) (*DescribeConfigResponse, error)

	// Add an inactive queue.
	// Will be automatically un-set by the relay if the queue receives new messages.
	AddInactiveQueue(context.Context, *AddInactiveQueueRequest) (*AddInactiveQueueResponse, error)

	// Remove an inactive queue.
	RemoveInactiveQueue(context.Context, *RemoveInactiveQueueRequest) (*RemoveInactiveQueueResponse, error)

	// List inactive queues.
	InactiveQueues(context.Context, *InactiveQueuesRequest) (*InactiveQueuesResponse, error)

	// Query for the current queue limit for an app.
	QueueLimits(context.Context, *QueueLimitsRequest) (*QueueLimitsResponse, error)

	// Set the queue limit for an app.
	SetQueueLimit(context.Context, *SetQueueLimitRequest) (*SetQueueLimitResponse, error)

	EnableFeature(context.Context, *EnableFeatureRequest) (*EnableFeatureResponse, error)

	DisableFeature(context.Context, *DisableFeatureRequest) (*DisableFeatureResponse, error)

	Features(context.Context, *FeaturesRequest) (*FeaturesResponse, error)

	// Query consumer group to topic mappings
	DescribeRelayGroups(context.Context, *DescribeRelayGroupsRequest) (*DescribeRelayGroupsResponse, error)
}

