// =====================

type AuthService interface {
	// Generate API key used for authorization header signature
	GenerateApiKey(context.Context, *GenerateApiKeyRequest) (*GenerateApiKeyResponse, error)

	// STAGING ONLY
	// Retrieve an API key. Makes testing auth config easier because users don't
	// need to acquire vault entitlements.
	GetApiKey(context.Context, *GetApiKeyRequest) (*GetApiKeyResponse, error)

	// Revokes access to an existing API key used for authorization
	RevokeApiKey(context.Context, *RevokeApiKeyRequest) (*EmptyResponse, error)

	// Validate that auth is working.
	Test(context.Context, *AuthTestRequest) (*EmptyResponse, error)
}

